registerRefData('nsw-cond-n-232',{"id":232,"pan":null,"ref":"DA2024/0612","address":"13 Coleridge Street Riverwood 2210,11 Coleridge Street Riverwood 2210,9 Coleridge Street Riverwood 2210,7 Coleridge Street Riverwood 2210,5 Coleridge Street Riverwood 2210,1 Coleridge Street Riverwood 2210","description":"Affordable Housing Residential Flat Building","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-09-08","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSSH-188!20250908T031634.375 GMT","sha256":"b744efc5e15d4086fd6dabc78ea036d57a3395e465f21cd293ddcd3456497ead","pages":52,"layout":"numbered","n":22,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/232.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/affordable-housing-residential-flat-building-3","lga":"GEORGES RIVER","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSSSH-188 - GEORGES RIVER - DA2024/0612","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Removal of trees and construction of a 4-storey residential flat building\ncomprising a total of 42 affordable housing units on a vacant allotment,\nwith basement parking for 19 vehicles, including associated site works,\nlandscaping, fencing and lot consolidation with dedication of land for a\npublic pathway","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 1-13 Coleridge Street, Riverwood NSW 2210 (Lots 7-12 DP 35640)","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER NSW Land and Housing Corporation / NSW Land and Housing Corporation","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Crown development over $5 million","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Housing) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Resilience and Hazards) 2021\no State Environmental Planning Policy (Sustainable Buildings) 2022\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021\no State Environmental Planning Policy (Transport and Infrastructure)\n2021\no Georges River Local Environmental Plan 2021\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Georges River Development Control Plan 2021\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment\nMATERIAL CONSIDERED BY\nTHE PANEL\n• Council Assessment Report: 19 August 2025\n• Amended draft conditions of consent with applicant comments dated\n29 August 2025\n• Letter of endorsement of draft conditions of consent, subject to final\namendments, provided by the applicant dated 29 August 2025\n• Revised Draft conditions Council memo dated 1 September 2025\n• Final draft conditions of consent and endorsement by applicant\nprovided on 2 September 2025.\n• Written submissions during public exhibition: 16 individual\nsubmissions, 1 petition (38 signatories), 2 representations\n• Verbal submissions at the public meeting:\no Hardeep Sidhu obo Coleridge St Riverwood Community, Darren\nGiles, Hady Heng\no Council assessment planner - Atalay Bas\no On behalf of the applicant - Carolyn Howell (Manager\nAssessment, Housing Portfolio, Homes NSW), Frances Beasley\n(Senior Planner, Assessment, Housing Portfolio, Homes NSW),\nBelinda McHarg (WMK Architecture, Director Projects), Nicole\nCork (WMK Architecture, Project Lead)\n• Total number of unique submissions received by way of objection: 17","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Site Inspection: 4 March 2025\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James, Christina Jamieson, Sam Stratikopoulos\no Council assessment staff: Ruth Bennett, Nicole Askew\no DPHI: Nikita Lange\n• Preliminary Briefing: 24 March 2025\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James, Christina Jamieson, Sam Stratikopoulos\no Council assessment staff: Ruth Bennett, Nicole Askew, Carine\nElias\no Applicant representatives: Carolyn Howell (Homes NSW),\no Deborah Gilbert (Homes NSW), Hammad Osmani (Homes NSW),\nAbhay Dave (Homes NSW), Puneet Sodhi (Homes NSW), John\nAndreas (WMK Architecture), Nicole Cork (WMK Architecture)\no DPHI: Amanda Moylan, Tracey Gillett\n• Status Briefing: 23 June 2025\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nGlennis James, Christina Jamieson, Sam Stratikopoulos\no Council assessment staff: Ruth Bennett, Atalay Bas, Geoffrey\nGarnsey, Firoz Ahmed\no Applicant representatives: Karl Harb, Carolyn Howell, Deborah\nGilbert, Hammad Osmani, Abhay Dave, Nicole Cork, Fouad\nHabbouche, Belind McHarg\no DPHI: Amanda Moylan, Nikita Lange\n• Status Briefing: 28 July 2025\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nChristina Jamieson, Sam Stratikopoulos\no Council assessment staff: Ruth Bennett, Atalay Bas, Roopali\nPandey, Firoz Ahmed, Geoffrey Garnsey\no Applicant representatives: Carolyn Howell (Homes NSW),\nDeborah Gilbert (Homes NSW), Hammad Osmani (Homes NSW),\nAbhay Dave (Homes NSW), Nicole Cork (WMK Architecture),\nFrances Beasley, Belinda McHarg\no DPHI: Nikita Lange\n• Final briefing to discuss Council’s recommendation: 1 September 2025\no Panel members: Annelise Tuor (Chair), Penelope Holloway,\nChristina Jamieson, Sam Stratikopoulos\no Council assessment staff: Ruth Bennett, Atalay Bas, Kristy\nGriffiths, Geoffrey Garnsey\no DPHI: Amanda Moylan","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":4},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report and further amended and","text":"agreed to by the Crown Applicant as attached in Schedule 2\nDEVELOPMENT CONSENT\nEnvironmental Planning and Assessment Act 1979\nDevelopment Application No: DA2024/0612\nAPPLICATION DETAILS\nApplicant: NSW Land & Housing Corporation - Deborah\nGilbert\nLand Description:\nProperty\nLots 7, 8, 9, 10, 11, 12 in DP 35640\n1-13 Coleridge Street RIVERWOOD NSW 2210,\nDevelopment: Removal of trees and construction of a 4-\nstorey affordable housing residential flat\nbuilding containing 42 units over basement car\nparking, including landscaping, site works,\nand dedication of land\nAuthority: Decision of the Sydney South Planning Panel\nUnder Section 4.16 of the Environmental Planning and Assessment Act 1979, South\nSydney Planning Panel has determined DA2024/0612 as described above, by the\ngranting of development consent subject to the conditions specified in this notice.\nThe following conditions of consent are imposed for the following reasons:\n(a) To ensure compliance with the terms of the relevant Environmental Planning\nInstrument and/or Building Code of Australia and/or Council’s codes, policies and\nspecifications.\n(b) To protect the environment.\n(c) To ensure that there is no unacceptable impact on the amenity of the area, or to private\nand public property.\n(d) It is in the public interest.\nSPECIFIC DEVELOPMENT CONDITIONS\nSCHEDULE A\nSpecific Development Conditions\nDEVELOPMENT DETAILS\nSCHEDULE 2 - Conditions of consent\nBEFORE COMMENCING BUILDING WORK, you must obtain a\nCrown Certificate.\n1. Approved Plans - The development must be implemented in accordance with the\napproved plans and supporting documentation listed below which have been\nendorsed by Council’s approved stamp, except where amended by conditions of this\nconsent:\nDescription Reference\nNo.\nDate Revision Prepared by\nCover Sheet DA000 18.10.2024 A WMK Architecture\nSurvey Plan DA002 18.10.2024 A WMK Architecture\nSite Analysis DA003 18.10.2024 A WMK Architecture\nSite Plan DA004 18.10.2024 A WMK Architecture\nDemolition Plan DA005 18.10.2024 A WMK Architecture\nBasement Plan DA006 18.10.2024 A WMK Architecture\nGround Floor Plan DA101 27.06.2025 B WMK Architecture\nLevel 01 Plan DA102 18.10.2024 A WMK Architecture\nLevel 02 Plan DA103 18.10.2024 A WMK Architecture\nLevel 03 Plan DA104 18.10.2024 A WMK Architecture\nRoof Plan DA105 18.10.2024 A WMK Architecture\nNorth and South\nElevation\nDA500 27.06.2025 B WMK Architecture\nEast and West\nElevation\nDA501 18.10.2024 A WMK Architecture\nStreetscape Elevation DA502 18.10.2024 A WMK Architecture\nSections 1 of 3 DA600 18.10.2024 A WMK Architecture\nSection 2 of 3 DA601 18.10.2024 A WMK Architecture\nSections 3 of 3 DA602 18.10.2024 A WMK Architecture\nRailway Sections DA603 18.10.2024 A WMK Architecture\nApartment Types 1\nof 3\nDA900 18.10.2024 A WMK Architecture\nApartment Types 2\nof 3\nDA901 18.10.2024 A WMK Architecture\nDDA Compliance 3\nof 3\nDA902 18.10.2024 A WMK Architecture\n3D Massing -\nHeight Plane\nDA910 18.10.2024 A WMK Architecture\nShadow Diagrams\n- Sheet 1\nDA920 18.10.2024 A WMK Architecture\nShadow Diagrams\n- Sheet 2\nDA921 18.10.2024 A WMK Architecture\nViews from Sun -\nSheet 1\nDA923 18.10.2024 A WMK Architecture\nViews from Sun -\nSheet 2\nDA924 18.10.2024 A WMK Architecture\nViews from Sun -\nCOS - Sheet 1\nDA925 18.10.2024 A WMK Architecture\nViews from Sun -\nCOS - Sheet 2\nDA926 18.10.2024 A WMK Architecture\nADG & SEPP\nCompliance Plans\nDA950 30.06.2025 B WMK Architecture\nSolar Access and\nCross Ventilation\nCompliance\nDA951 30.06.2025 B WMK Architecture\nGFA Area Plans DA960 18.10.2024 A WMK Architecture\nDevelopment\nSummary\nDA970 18.10.2024 A WMK Architecture\nPhotomontage DA990 18.10.2024 A WMK Architecture\nCoversheet SK00 June 2025 J Umbaco Landscape\nArchitects\nTree Protection\nPlan\nSK0X October\n2024\nH Umbaco Landscape\nArchitects\nLandscape\nConcept Plan\nSK01 June 2025 J Umbaco Landscape\nArchitects\nPlant Material 1 SK02 October\n2023\nH Umbaco Landscape\nArchitects\nPlant Material 2 SK03 October\n2023\nH Umbaco Landscape\nArchitects\nLandscape\nDetails\nSK04 October\n2024\nH Umbaco Landscape\nArchitects\nThe following documents and plans have been reviewed in\nassessing the proposal:\n(a) “Siteworks and Drainage Basement 1”, Project No. S21255,\nDrawing No. CI -0200, Rev G, Dated 26/06/2025, Prepared\nby BG&E - Sydney Office.\n(b) “Siteworks and Drainage Ground Floor”, Project No. S21255,\nDrawing No. CI -0201, Rev G, Dated 26/06/2025, Prepared\nby BG&E - Sydney Office.\n(c) “OSD Plan”, Project No. S21255, Drawing No. CI-0350, Rev\nD, Dated 16/06/2025, Prepared by BG&E - Sydney Office.\n(d) “OSD Sections and Details”, Project No. S21255, Drawing\nNo. CI-0351, Rev D, Dated 16/06/2025, Prepared by BG&E\n- Sydney Office.\n(e) “Detail and Contour Survey”, Job No. 211648, dated\n29/09/2021, prepared by Land and Housing Corporation.\n(f) “Proposed Subdivision Plan”, Drawing No. DA006, dated\n27/06/2025, prepared by WMK Architecture\n(g) Statement of Environmental Effects dated December 2024,\nprepared by Homes NSW, department reference number\nD24/3382288\n(h) Acoustic Report prepared by Pulse White Noise Acoustics ,\ntitled DA Acoustic Assessment, version R3, and dated 1\nNovember 2024,\n(i) Site Waste Minimisation and Management Plan prepared by\nWMK Architecture, submitted as Appendix Y\n(j) Arboricultural Impact Assessment prepared by Creative\nPlanning Solutions, Project No E784, dated 30 June 2025,\nRevision B\n(k) Design Report entitled Architectural SEPP (Housing) 2021\nDesign Statement by WMK Architecture dated 1.11.2024,\nRevision 5\n(l) BCA Report prepared by BCA Vision dated 11.09.2024\n(m) Access Report entitled DA Access Report - Final prepared\nby MGAC, Job Number 00037 dated 31.10.2024\n(n) BASIX Certificate number BSX- 27882M_02 dated 29.10.24\nprepared by Building Services Engineers\nNote: Crown Building Work - Pursuant to Section 6.28 of\nthe Environmental Planning and Assessment Act 1979,\nCrown building, demolition and incidental work cannot be\ncommenced to be carried out unless the Crown building and\nother development work is certified by or on behalf of the\nCrown to comply with the technical provisions of the State’s\nbuilding laws including the Building Code of\nAustralia/National Construction Code. It is the responsibility\nof the Crown Authority to ensure this statutory provision of\nthe Act is complied with.\nSEPARATE APPROVALS REQUIRED UNDER OTHER\nLEGISLATION\n2. Council Requirements for Works on Public\nInfrastructure\nAll proposed works within the public road and footway shall be\ndesigned and constructed to Council’s standards and\nspecifications and a copy of the detailed plans submitted to\nCouncil prior to work commencing. The applicant/developer shall\narrange for necessary inspections by Council whilst the work is in\nprogress or after completion of the works.\n3. Below ground anchors - Information to be submitted\nprior to construction\nIn the event that the excavation associated with the\nbasement carpark is to be supported by the use of below\nground (cable) anchors that are constructed under\nCouncil’s roadways/footways, Council must be advised and\nthe following details must be submitted:\n(a) That cable anchors will be stressed released when the\nbuilding extends above ground level to the satisfaction of\nCouncil.\n(b) The applicant has indemnified Council from all public liability\nclaims arising from the proposed works, and provide\nadequate insurance cover to the satisfaction of council.\n(c) Documentary evidence of such insurance cover to the value\nof $20 million.\n(d) A certificate is to be submitted to Council from a structural\nengineer verifying that the cables have been stress released.\n(e) That in the event of any works taking place on Council’s\nroadways/footways adjoining the property while the\nanchors are still stressed, all costs associated with\novercoming the difficulties caused\nby the presence of the ‘live’\nanchors will be borne by the applicant.\n4. Vehicular Crossing - Major Development\nThe following vehicular crossing and road frontage works will be\nrequired to facilitate access to and from the proposed\ndevelopment site:\ni. Construct a 1.2m wid e footpath extending from the\nwestern end of the communal open space to the existing\npathway and connecting to that pathway at a joint no less\nthan 2m past the eastern boundary of No. 15 Coleridge\nStreet. This is to be an all-weather use pathway along the\nColeridge Street frontage\nii. The pathway shall be designed and constructed as\nfollows:\nA. With porous paving, Flexipave 40mm\nthickness. Any excavation is limited to\nhand excavation around the tree root\nzone.\nB. Design and construct the footpath so\nthat the top level is at the existing\nsurface level.\nC. The pathway should be 300mm from\nthe tree trunk.\nD. At levels that minimise the impact on\nthe Structural Root Zone (SRZ) of each\nindividual street tree.\nE. That limits root pruning within the\nNotional Root Zone (NRZ) to roots less\nthan 50mm in diameter not exceeding\n10% of the total root plate mass\nvolume.\n(a) Construction of a 1.5m wide footpath for the dedicated land\n(public path link -up), in accordance with Council’s\nSpecifications for footpath, applying at the time\nconstruction approval is sought.\n(b) The thickness and design of the driveway shall be in\naccordance with Council’s Specifications applying at the\ntime construction approval is sought.\n(c) Construct a new 150mm high concrete kerb with 450mm\nwide gutter for the full frontage(s) of the site in accordance\nwith Council’s Specifications for kerb and guttering,\napplying at the time construction approval is sought.\n(d) Any existing vehicular crossing and/or laybacks which are\nredundant must be removed. The kerb and gutter, any other\nfootpath and turf areas shall be restored at the expense of\nthe applicant. The work shall be carried out in accordance\nwith Council’s specification, applying at the time\nconstruction approval is sought.\n5. Inspection of Council Infrastructure\nIn order to insure against damage to Council property the following is required:\n(a) Prior to the commencement of works, p ay Council a non -\nrefundable inspection fee to enable assessment of any\ndamage and repairs where required: $385.00 per frontage.\n(b) Submit to Council, before the commencement of work, a\ndilapidation report of the condition of the Council nature\nstrip, footpath and driveway crossing, or any area likely to\nbe affected by the proposal.\nAt the completion of work Council will review the dilapidation\nreport and the Works-As-Executed Drawings (if applicable) and\ninspect the public works.\nREQUIREMENTS OF CONCURRENCE, INTEGRATED & OTHER\nGOVERNMENT AUTHORITIES\n8. APT Petroleum Pipelines Pty Ltd - APA\n1. Risk Assessment Required\nPrior to the development commencing, a Risk Assessment considering\nthe requirements of Australian Standards 2885 for Pipelines - Gas and\nLiquid Petroleum, must be conducted by APA in conjunction with the\napplicant and its recommendations/actions must be implemented to the\nsatisfaction of Gorodok Pty Limited (APA).\n2. Third Party Works Authorisation\nPrior to the commencement of any works within 3 meters of the gas\ntransmission pipeline, the proponent must seek a third party works\nauthorisation from APA for approval. Works approved by APA must\ncomply with any conditions attached to a third party works approval.\n3. Easement Delineation On Site\nDuring demolition works, the boundary of the easement must be clearly\ndelineated on site by temporary fencing (or other means as agreed by\nAPA), and clearly marked as a hazardous work zone/ restricted area.\n4. Pipeline Delineation On Plans\nAll plans which include the area of the ethane transmission pipeline easement\nmust have the easement clearly identified with hatching 3m either side of the\neasement. The area must also be clearly labelled as ‘high pressure gas pipeline\nright of way - no works to occur without the prior authorisation of the\npipeline operator’.","stage":"general","stage_basis":"heading","page":4},{"label":"13","code":null,"number":"13","title":"Photinia robusta Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"14","code":null,"number":"14","title":"Pittosporum undulatum Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"15","code":null,"number":"15","title":"Ligustrum lucidum Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"16","code":null,"number":"16","title":"Ligustrum lucidum Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"17","code":null,"number":"17","title":"Ligustrum lucidum Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"18","code":null,"number":"18","title":"Ficus benjamina Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"19","code":null,"number":"19","title":"Cupressus sempervirens Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"20","code":null,"number":"20","title":"Cupressus sempervirens Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"21","code":null,"number":"21","title":"Cupressus sempervirens Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"22","code":null,"number":"22","title":"Cupressus sempervirens Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"23","code":null,"number":"23","title":"Syagrus romanizoffiana Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"24","code":null,"number":"24","title":"Melaleuca quinquenervia Within site","text":"","stage":"general","stage_basis":"heading","page":33},{"label":"25","code":null,"number":"25","title":"Syagrus romanizoffiana Within site","text":"29 Schefflera actinophylla Within site\n33 Pittosporum undulatum Within site\n34 Ligustrum sinense Within site\nNote: refer to Arboricultural Impact Assessment Report prepared by\nCPS, for tree numbering and location only.\na) The Tree Location Plan, Appendix 2, created by CPS, shall be\nutilised prior and during the project to ensure this tree\nlocation plan and tree protection is adhered too.\nb) All tree removal shall be carried out by a minimum AQF Level\n3 Arborist with appropriate insurance. Tree removal is to be\nundertaken safely and in compliance with AS 4373 - 2007\nPruning of Amenity Trees and Tree Works Industry Code of\nPractice (Work Cover NSW 1.8.98).\n50. Tree Protection\na) All trees upon adjoining site s must be protected in\naccordance with Australian Standards AS4970 -2025,\nProtection of Trees on Development Sites.\nb) The project AQF 5 Arborist shall be in attendance to provide\nguidance, during the excavations within the NRZ, of Council’s\nStreet trees.\nc) The storage or mixing of materials, washing equipment,\ndisposal of liquids or building materials, site sheds etc. must\nnot occur within 5 meters of the truck of any tree (inc.\nneighbouring trees).\nd) Without prejudice to cause (c) above, any excavation works\nwithin the NRZ of any tree must be referred to the Site\nArborist with regards to tree protection, prior to the\ncommencement of the works. All excavation works within\nthe TPZ of any tree must be undertaken using non -\ndestructive methods (by hand/ Airspade/ hydro -vac etc.) to\nensure no tree root greater than 30mm diameter or section\nof root mass are damaged, pruned or removed.\ne) Footings/piers/posts must be relocated / realigned if any tree\nroot greater than 30mm diameter is present. A minimum of\n150mm clearance must be provided between the\nfooting/piers/posts and tree root.\nf) Alternative installation methods for services such as\nredirection of services or directional boring must be\nemployed where roots greater than 30mm diameter or a\nsection of root mass (palm tree roots) are encountered\nduring the installation of any services within the TPZ of any\ntree.\ng) Written approval from the project arborist must be obtained\nprior to undertaking of any tree pruning works or pruning of\nany tree roots greater than 30mm diameter.\nh) Any damage to existing trees as a result of construction\nactivities must be immediately reported to Council’s\nLandscape & Arboriculture Assessment Officer. Any damage\nto existing trees as a result of construction activities may\nresult in a prosecution under the Local Government Act 1993\nand/or the Environmental Planning Assessment Act 1979.\ni) Trees specified for retention are to be inspected, monitored\nand remedial work undertaken as required during and after\ncompletion of development works by a qualified AQF Level 5\nProject Arborist. Regular inspections and documentation\nfrom the Arborist to t he Crown Certifier and Council’s Tree\nCompliance Officer are required at the following hold points:\nHold Point Action Required by AQF Level 5 Project\nArborist\n1. a) Prior to commencement\nof demolition/construction\nworks.\nSite meeting with builder to discuss and\nconfirm understanding of tree protection\nmeasures required for Council’s street trees.\n1. b) Prior to commencement Supervise and certify installation of tree\nof demolition/construction\nworks.\nprotection measures for Council’s Street\ntrees. Tree protection measures are to be\ninstalled as per the approved Tree Protection\nPlan. Clear and dated photographs of the\ninstalled tree protection fencing must be\nsubmitted to Council.\n2. Works within the TPZ areas\nof trees to be retained.\nSupervise, direct and photograph all\napproved works with the TPZ areas of tree to\nbe retained.\na) During demolition of any existing structure\nwithin close proximity to Tree Protection\nZones (TPZ);\nb) During any excavation, trenching or\nconstruction that has been approved by\nCouncil within the TPZ of any tree to be\nretained;\nc) During any landscape works within the TPZ\nof any tree to be retained.\n3. Arboricultural Compliance\nReport.\nInspect, photograph and report on tree health\nand condition, maintenance of tree protection\nmeasures and remedial tree works as\nrequired.\na) Certification tree protection measures have\nbeen installed in accordance with the\nconditions prior to the commencement of\nworks;\nb) Certification of compliance with each key\nmilestone listed above within 48 hours of\ncompletion;\nc) Details of any other works undertaken on\nany tree to be retained or with TPZ(s);\nd) A final compliance report shall be\nsubmitted to the Crown Certifier prior to\nOccupation.\n4. Prior to Occupation Final inspection of trees to be retained and\nprovision of follow up report detailing activities\nduring construction including any damage to\nthe trees and any remedial work required to\nensure the ongoing health and structural\nstability of the trees and/or replacement trees\nrequired. Any recommendations for remedial\nwork and/or replacement trees will be\nrequired to be supported in writing by the\nproject arborist and actioned prior to the\noccupation of the development.\n51. Landscape Works\nAll landscape works shall be carried out in accordance with the\napproved landscape plans and specifications, except where\namended by this consent. The landscaping shall be maintained in\naccordance with the approved plans in perpetuity, subject to the\nfollowing -\na) The applicant must engage a licensed and reputable nursery\ngrower early within the build phase and purchase all trees\nand plant material early to ensure that all tree and plant\nmaterial, pot/bag sizes and quantities are guaranteed at the\ntime of the landscape and planting phase.\nb) All of the ‘feature trees small / medium’ shown on the\napproved Landscape Plans must be a minimum of 75L pot/bag\nsize and a minimum of 1.5m tall at the time of planting.\nc) New tree plantings must be grown to AS 2303 - 2018, Tree\nStock for Landscape use and be planted by a Horticulturalist\nor AQF level 3 Arborist.\n52. Public Utility and Telecommunication Assets\nThe owner shall bear the cost of any relocation or modification\nrequired to any Public Utility Authority assets including\ntelecommunication lines & cables and restoring any footpath,\nroadway and any other Council assets damaged due to works at,\nnear or associated with the site.\n53. Clause 74 EPAR 2021 - Shoring and adequacy of\nadjoining premises - If the development involves\nexcavation that extends below the level of the base of the\nfootings of a building on adjoining land, this prescribed\ncondition requires the person who benefits from the\ndevelopment consent to protect and support the adjoining\npremises and where necessary underpin the adjoining\npremises to prevent any damage.\n54. Clause 74 EPAR 2021 Site Excavation\nExcavation of the site is to extend only to that area required for\nbuilding works depicted upon the approved plans. All excess\nexcavated material shall be removed from the site.\nAll excavations and backfilling associated with the erection or\ndemolition of a building must be executed safely and in\naccordance with appropriate professional standards.\nAll excavations associated with the erection or demolition of a\nbuilding must be properly guarded and protected to prevent them\nfrom being dangerous to life or property.\nIf the soil conditions require it, retaining walls associated with the\nerection or demolition of a building or other approved methods\nof preventing movement of the soil shall be provided and\nadequate provision shall be made for drainage.\nPRIOR TO OCCUPATION OF THE DEVELOPMENT\n55. BASIX Commitments - All energy efficiency measures as detailed in\nthe approved BASIX Certificate No. BSX-27882M_02 dated 29\nOctober 2024 must be implemented before occupation.\n56. BASIX Compliance Certificate\nA Compliance Certificate must be provided to the Crown Certifier\nregarding the implementation of all energy efficiency measures as\ndetailed in the approved BASIX Certificate before occupation.\n57. Section 73 Compliance Certificate - A Section 73 Compliance\nCertificate under the Sydney Water Act 1994\n<http://legislation.nsw.gov.au/> must be submitted to the Crown\nCertifier prior to Occupation.\n58. Acoustic Certification\nPrior to occupation, or use of the premises, a report prepared by a\nsuitably qualified acoustic consultant or engineer must be\nsubmitted to the Crown Certifier, certifying that the construction\nhas incorporated the recommendations in the Acoustic Report as\nreferenced in this consent.\nReason: To ensure appropriate acoustic level to surrounding\namenities.\n59. Compliance with Acoustic Report - Mechanical Plants\nPrior to occupation, a report prepared by a suitably qualified\nacoustic consultant must be submitted to the satisfaction of the\nCrown Certifier, certifying that the recommendations of the\nacoustic report submitted for the operation of mechanical plant\nand equipment have been implemented. The report must:\n(a) Include Test results demonstrating that the operation of the\nmechanical plant and equipment does not give rise to a sound\npressure level at any affected premises that exceeds the\nbackground LA90, 15 min noise level, measured in the\nabsence of the noise sources under consideration, by more\nthan 5dB(A).\n(b) demonstrate compliance with the Protection of the\nEnvironment Operations Act.\nThe Acoustic Certification must be incorporated into the\ndocumentation submitted to the Crown Certifier prior to\noccupation.\nReason: To ensure appropriate acoustic levels to maintain the\nsurrounding amenity.\n60. Acoustic Compliance - General Operation of Premises\nA suitably qualified acoustic consultant or engineer must certify\nthat the operation of the plant and equipment complies with the\nNSW Environment Protection Authority’s “Noise Policy for Industry\n(2017)” (as amended).\nThe Acoustic Certification must be submitted to the Crown Certifier\nprior to occupation or use of the premises.\nThe Acoustic Certification must be incorporated into the\ndocumentation provided to the Crown Certifier.\nReason: To ensure appropriate acoustic level to surrounding\namenities.\n61. Lighting - General Nuisance\nAny lighting on the premises must be designed and installed so as\nnot to cause a nuisance to other residents in the area or motorists\non nearby roads by light overspill or glare.\nReason: To protect neighbourhood amenity and road safety.\n62. General amenity of the neighbourhood\nThe implementation of the development must not adversely affect\nthe amenity of the neighbourhood or interfere unreasonably with\nthe comfort or repose of a person who is outside the premises by\nreason of due to the emission or discharge of noise, fumes, vapour,\nodour, steam, soot, dust, wastewater, waste products, grit, oil or\nother harmful products.\nReason: To protect the neighbourhood amenity.\n63. Vehicular crossing and Frontage work - Major development\nThe following road frontage works shall be constructed in\naccordance with the specifications issued by Council’s Assets and\nInfrastructure Division:\n(a) Construction of a 1.2m wide footpath, in accordance with\nplans that demonstrate the following:\niAn all-weather use pathway of not less than 1.2m wide\nalong the Coleridge Street frontage extending from the\nwestern end of the communal open space to the existing\npathway and connecting to that pathway at a joint not less\nthan 2m past the eastern boundary of No.15 Coleridge\nStreet.\niiThe pathway shall be designed and constructed as\nfollows:\nA.With porous paving, Flexipave 40mm\nthickness. Any excavation is limited to\nhand excavation around the tree root zone.\nB.Design and construct the footpath so that\nthe top level is at the existing surface level.\nC.The pathway should be 300mm from the\ntree trunk.\nD.At levels that minimise the impact on the\nStructural Root Zone (SRZ) of each\nindividual street tree.\nE.That limits root pruning within the\nNotional Root Zone (NRZ) to roots less than\n50mm in diameter not exceeding 10% of\nthe total root plate mass volume.\n(b) Construct the driveway crossing in accordance with\nCouncil’s specifications for vehicular crossings.\n(c) Construct a new 150mm high concrete kerb with 450mm\nwide gutter for the full frontage(s) of the site in accordance\nwith Council’s Specifications for kerb and guttering.\n(d) Any existing vehicular crossing and/or laybacks which are\nredundant must be removed. The kerb and gutter, any other\nfootpath and turf areas shall be restored at the expense of\nthe applicant and in accordance with Council’s Specification\nfor Driveway Crossings and Associated Works.\nA private contractor shall carry out the above work, at the\nexpense of the applicant and in accordance with Council’s\nSpecification for Driveway Crossings and Associated Works.\nThe driveway and road frontage works are to be completed\nbefore Occupation.\n64. Completion of Major Works\nPrior to Occupation, the following works must be completed at\nthe applicant’s expense to the satisfaction of the Crown Certifier:\n(a) Stormwater pipes, pits and connections to public\nstormwater systems within the road related area;\n(b) Driveways and vehicular crossings within the road related area;\n(c) Removal of redundant driveways and vehicular crossings;\n(d) New footpaths within the road related area;\n(e) Relocation of existing power/light pole;\n(f) Relocation/provision of street signs;\n(g) New or replacement street trees;\n(h) New footway verges, where a grass verge exists, the balance\nof the area between the footpath and the kerb or site\nboundary over the full frontage of the proposed\ndevelopment must be turfed. The grass verge must be\nconstructed to contain a uniform minimum 75mm of friable\ngrowing medium and have a total cover of turf predominant\nwithin the street;\n(i) New or reinstated kerb and guttering within the road related area; and\n(j) New or reinstated road surface pavement within the road.\n65. Post Construction Dilapidation report - Private Land\nAt the completion of the construction works, a suitably qualified\nperson is to be engaged to prepare a post-construction\ndilapidation report. This report is to ascertain whether the\nconstruction works associated with the subject development\ncreated any structural damage to the adjoining premises.\nThe report is to be prepared at the expense of the applicant and\nsubmitted to the Crown Certifier prior to occupation.\nEvidence confirming that a copy of the post-construction\ndilapidation report was delivered to the adjoining properties\nsubject of the dilapidation report must be provided to the Crown\nCertifier prior to occupation.\n66. Major Development\nInternal driveways and parking spaces are to be adequately\npaved with concrete or bitumen, or interlocking pavers to\nprovide a dust-free surface. All car parking spaces are to be line\nmarked in accordance with AS1742, ‘Australian Standard Manual\nof Uniform Traffic Control Devices’ and the relevant guidelines\npublished by the TfNSW.\n67. Section 73 Compliance Certificate\nA Section 73 Compliance Certificate under the Sydney Water Act\n1994 must be submitted to the Crown Certifier prior to\noccupation.\n68. Restriction to User and Positive Covenant for On -Site Detention\nFacility\nA Restriction on Use of the Land and Positive Covenant shall be\ncreated and registered on the title of the property, which places\nthe responsibility for the maintenance of the on-site stormwater\nmanagement system on the owners of the land. The terms of\nthe instrument are to be in accordance with Council’s standard\nterms and restrictions which are as follows;\nRestrictions on Use of Land\nThe registered proprietor shall not make or permit or suffer the\nmaking of any alterations to any on-site stormwater\nmanagement system which is, or shall be, constructed on the\nlot(s) burdened without the prior consent in writing of Georges\nRiver Council. The expression “on-site stormwater management\nsystem” shall include all ancillary gutters, pipes, drains, walls,\nkerbs, pits, grates, tanks, chambers, basins and surfaces\ndesigned to manage stormwater quantity or quality including the\ntemporary detention or permanent retention of stormwater\nstorages. Any on-site stormwater management system\nconstructed on the lot(s) burdened is hereafter referred to as\n“the system.\nName of Authority having the power to release, vary or modify\nthe Restriction referred to is Georges River Council.”\nPositive Covenants\n1. The registered proprietor of the lot(s) hereby burdened will in\nrespect of the system:\na) keep the system clean and free from silt, rubbish and\ndebris\nb) Maintain and repair at the sole expense of the registered\nproprietors the whole of the system so that if functions in a\nsafe and efficient manner\nc) Permit the Council or its authorised agents from time to\ntime and upon giving reasonable notice (but at any time and\nwithout notice in the case of an emergency) to enter and\ninspect the land for the compliance with the requirements of\nthis covenant\nd) Comply with the terms of any written notice issued by the\nCouncil in respect of the requirements of this covenant\nwithin the time stated in the notice.\n2. Pursuant to Section 88F (3) of the Conveyancing Act 1919 the\nCouncil shall have the following additional powers:\na) in the event that the registered proprietor fails to comply\nwith the terms of any written notice issued by the Council as\nset out above the Council or its authorised agents may enter\nthe land with all necessary materials and equipment and\ncarry out any work which the Council in its discretion\nconsiders reasonable to comply with the said notice referred\nto in part 1(d) above\nb) The Council may recover from the registered proprietor in\na Court of competent jurisdiction:\ni. any expense reasonably incurred by it in exercising its\npowers under subparagraph (i) hereof. Such expense shall\ninclude reasonable wages for the Council’s employees\nengaged in effecting the work referred to in (i) above,\nsupervising and administering the said work together with\ncosts, reasonably estimated by the Council, for the use of\nmaterials, machinery, tools and equipment in conjunction\nwith the said work.\nii. legal costs on an indemnity basis for issue of the said\nnotices and recovery of the said costs and expenses together\nwith the costs and expenses of registration of a covenant\ncharge pursuant to section 88F of the Act or providing any\ncertificate required pursuant to section 88G of the Act or\nobtaining any injunction pursuant to section 88H of the Act.\nName of Authority having the power to release vary or\nmodify the Positive Covenant referred to is Georges River\nCouncil.\n69. Maintenance Schedule - On-site Stormwater Management\nA Maintenance Schedule for the proposed on- site stormwater\nmanagement measures is to be prepared and submitted to\nCouncil. The Maintenance Schedule shall outline the required\nmaintenance works, how and when these will be done and who\nwill be carrying out these maintenance works.\n70. Traffic Control Devices\nThe internal road network, pedestrian facilities and parking\nfacilities (including visitor parking and employee parking) shall be\ndesignated and line marked in accordance with Australian\nStandard - AS1742, Manual of Uniform Traffic Control Devices.\nIf an exit from car park utilises a pedestrian footpath, then a\nwarning system such as flashing light and/or ‘alarm sound’ must\nbe installed on the subject property to alert pedestrians of\nvehicles exiting the car park. The Alarm System must be designed\nand installed in accordance with AS2890.1 -2004.\n71. Dilapidation Report on Public Land for Major Development Only\nUpon completion of works, a follow up dilapidation report must\nbe prepared for the items of Council infrastructure adjoining the\ndevelopment site including:\n(a) Footpaths, Kerb and gutter\n(b) Drainage Infra-structure\nThe dilapidation report must be prepared by a professional\nengineer specialising in structural engineering, and\ninclude:\n(a) Photographs showing the condition of the road pavement\nfronting the site\n(b) Photographs showing the condition of the kerb and gutter\nfronting the site\n(c) Photographs showing the condition of the footway\nincluding footpath pavement fronting the site\n(d) Photographs showing the condition of retaining walls\nwithin the footway or road\n(e) Closed circuit television/video inspection (in DVD format)\nof public stormwater drainage systems fronting, adjoining\nor within the site, and\n(f) The full name and signature of the professional engineer.\nThe report must be provided to the Crown Certifier and a copy\nprovided to the Council. The reports are to be supplied in\nelectronic format in Word or PDF. Photographs are to be in colour,\ndigital and date stamped.\nNOTE: Council will use this report to determine whether or not to\nrefund the damage deposit.\nCouncil’s Assets and Infrastructure Division must advise in writing\nthat the works have been completed to their satisfaction prior to\noccupation.\n72. Stormwater drainage works - Works As Executed\nPrior to occupation, storm water drainage works are to be\ncertified by a professional engineer specialising in hydraulic\nengineering, with Works -As-Executed drawings supplied to\nCouncil detailing:\n(a) Compliance with conditions of development consent\nrelating to stormwater;\n(b) The structural adequacy of the water quality tank and the\nstructural certification from qualified consulting structural\nengineer involved in the design of the tank structures;\n(c) That the works have been constructed in accordance with\nthe approved design in accordance with the submitted\ncalculations;\n(d) Pipe and pits invert levels and surface levels to Australian\nHeight Datum;\n(e) Contours indicating the direction in which water will flow\nover land should the capacity of the pit be exceeded in a\nstorm event exceeding design limits.\n(f)\nThe Work-As-Executed plans are prepared on the copies\nof the approved drainage plans issued with the\nconstruction documentation and variations are marked in\nred ink;\n(g)\nThe Work-As-Executed plans have been jointly prepared\nand duly signed by registered surveyor and consulting\ndrainage design engineer certifying the accuracy of\ndimensions, invert levels, surface levels, storage volume\netc, when all the site engineering works are completed\nand shall be submitted to the Crown Certifier and the\nCouncil (for record of WAE plans) prior to occupation.\n(h)\nThis Plan and Certification shall confirm that the design\nand construction of the stormwater drainage system\nsatisfies the conditions of development consent and the\nstormwater design details approved prior to construction\nby the Crown Certifier.\n73. Amalgamation of Six Lots into a Single Lot prior to Occupation - All\nsix lots shall be amalgamated into a single lot and a Deposited Plan\n(with Administration Sheet) is to be prepared by a Registered\nSurveyor and submitted to NSW Land Registry Services prior to\noccupation. .\n74. Public Pathway - Land Dedication to Council\nThe applicant shall dedicate the area shown on the ‘Proposed\nSubdivision Plan’ referenced in Condition No. 1. This area shall be\ndedicated as a public pathway to link Coleridge Street with Phillip\nStreet Reserve. The final plan of subdivision must be prepared by\na Registered Surveyor and submitted to Council with an\napplication for a Subdivision Certificate.\nThis Plan shall be submitted to council prior to occupation and\nregistered at the NSW Land Registry Services within 6 months of\noccupation.\n75. Arborist Supervision and Reporting\nAn Arboricultural Compliance Report prepared by an AQF Level 5\nArborist which includes photographic evidence and details of the\nhealth and condition of trees, must be submitted to Council’s\nSenior Landscape and Arboricultural Assessment Officer for their\nrecords prior to occupation. The Arborist must certify compliance\nwith each key milestone below:\n(a) Installation of tree protection measures in accordance\nwith conditions;\n(b) During demolition of structures and/or excavation of\nground surfaces that has been approved by Council within\nthe TPZ of any tree to be retained;\n(c) During any other works including landscaping within the TPZ\nof any tree to be retained.\n76. Completion of Landscape Works\nAll landscape works, the planting of all tree and plant material in\naccordance with approved landscape plans and specifications and\nconditions of consent, must be completed prior to occupation. A\ncertificate of compliance for the planting of all trees and shrubs\nproposed for the site must be prepared by a qualified\nHorticulturist, Landscape Designer or AQF Level 5 Arborist and\nsubmitted to the Crown Certifier for approval prior to occupation.\nOPERATIONAL CONDITIONS (ON-GOING)\n77. Noise Control - The use of the premises must not give rise to the\ntransmission of offensive noise to any place of different occupancy.\nOffensive noise is defined in the Protection of the Environment\nOperations Act 1997 (as amended).\nReason: To protect the neighbourhood amenity.\n78. Outdoor Lighting - To avoid annoyance to the occupants of\nadjoining premises or glare to motorists on nearby roads, outdoor\nlighting must comply with AS 4282 -2019: Control of the obtrusive\neffects of outdoor lighting.\n79. Lighting - General Nuisance - Any lighting on the site shall be\ndesigned so as not to cause a nuisance to other residences in the\narea or to motorists on nearby roads and to ensure no adverse\nimpact on the amenity of the surrounding area by light overspill or\nglare.\nFlashing, moving or intermittent lights or signs are prohibited.\n80. Activities and storage of goods outside buildings - Any work or\nactivity associated with the use of this development consent,\nincluding storage, or depositing of any goods or maintenance of\nany machinery shall be conducted within the building. External\nstorage shall be limited to waste receptacles.\nReason: To protect public amenity.\n81. Acoustic mitigation infrastructure - Maintenance - Noise\nmitigation measures as outlined in the Acoustic Report prepared\nby Pulse White Noise Acoustics , titled DA Acoustic Assessment,\nversion R3, and dated 1 November 2024, must be maintained at all\ntimes to ensure their acoustic performance does not diminish.\nReason: To provide appropriate acoustic levels to maintain the\nsurroundings.\n82. Residential - Domestic Air conditioner - The air conditioner must\nbe installed, located and used in a manner that does not emit noise\nexceeding 5dB(A) above the background noise level at the closest\nsensitive receiver when measured at the nearest neighbouring\nboundary.\nIn addition, when operated, the air conditioner must not be heard\nwithin a habitable room in any other residential premises\n(regardless of whether any door or window to that room is open)\nbefore:\n(a) 8am or after 10pm on any Sunday or public holiday, or\n(b) 7am or after 10pm on any other day.\nReason: To comply with legislation and protect neighbourhood\namenity.\n83. On-going Operational Waste Management\n(a) The applicant must allow bin storage at the following ratios:\ni. 120L general waste per unit per week - equivalent to:\n21 x 240L general waste bins per week, serviced once\nweekly, OR 8 x 660L general waste bins per week,\nserviced once weekly, OR 5 x 1,100L general waste bins\nper week, serviced once weekly,\nii. 120L recycling per unit per week - equivalent to: 21 x\n240L general waste bins per week, serviced once\nweekly, OR 8 x 660L general waste bins per week,\nserviced once weekly, OR 5 x 1,100L general waste bins\nper week, serviced once weekly,\niii. 120L organics per unit per week equivalent to: 17 x\n240L organic waste bins per week, serviced once\nweekly.\nReason: To ensure that the bin storage and collection\nprovisions are suitable for Council to provide a waste\nmanagement service\n(b) Bin and bulky waste storage areas are to be sufficiently\ndimensioned to allow for the easy movement of bins to and from\nthe kerbside/interim storage area during collection and must have\nappropriately sized doors for the size of bin to be used. The path\nof travel for bins must be level, at an appropriate grade, well-lit and\nwithout stairs, in addition to being in accordance with the BCA. The\ndesignated bin and waste storage areas are required to be a size\nappropriate for the storage of the waste volumes generated at the\nsite. All bin and waste storage areas are to be appropriately lit\n(sensor lighting recommended), drained to sewer with a water\noutlet for bin washing/cleaning and not visible from the public\ndomain unless secured behind wall/roof.\n(c) The path of bin travel must be free from stairs, well -lit (sensor\nlighting recommended) at an appropriate grade for a ramp as per\nthe Building Code of Australia and be a width appropriate for the\nmovement of bins up to 1,100L in width in accordance with AS\n4123.1-2008 Mobile Waste Containers.\n(d) NSW Land and Housing Corporation shall also be responsible for\nmaintaining all equipment, systems, facilities and storage areas\nused in conjunction with the provision of waste management\nservices in accordance with all applicable regulatory\nrequirements, relevant health and environmental standards, and\nto the satisfaction of Council.\n(e) All bin and waste storage areas are to be maintained in clean, safe\nand hygienic manner. In the event bin or waste storage areas are\nnot maintained in an appropriate manner, Council will advise\nNSW Land and Housing Corporation in writing to ensure the issue\nis rectified.\n(f) All waste handling equipment and systems used in conjunction\nwith the provision of waste and recycling services shall be\nmanufactured, installed and maintained in accordance with any\napplicable regulatory requirements, relevant Australian\nStandards, and relevant manufacturer’s specifications.\nThe management of all bin and waste storage areas throughout\nthe development are the responsibility of the NSW Land and\nHousing Corporation to maintain in a clean manner.\n(g) Council can provide educational information in the form of bin\nstickers and/or bin storage area posters and signage. It will be the\nresponsibility of the Building Manager to install such signage to\nassist with the correct use of the Council waste collection service.\n(h) Participation in and use of the Wheel Out Wheel Back (WOWB)\ncollection service is subject to site Risk Assessment and safe\naccess by Council’s waste collection contractor, determined both\nprior to the service commencing, and/or as required during on-\ngoing waste collection services provided to the property. The\nWOWB service can be cancelled at Council’s discretion in which\ncircumstance the site may be required to arrange bin\npresentation on the kerbside. It is the responsibility of the NSW\nLand and Housing C orporation to maintain the waste storage\nareas as clean and tidy. In the event it is not, Council reserves the\nright to cancel the WOWB service.\n(i) In the event the development cannot be serviced by Council’s\nwaste management contractor once the site is operational, the\nNSW Land and Housing Corporation is required to consult with\nCouncil’s waste team to ensure a suitable solution is found if any\nissues arise. In the event a suitable solution is not found it will be\nthe responsibility of the NSW Land and Housing Corporation for\nengaging a private waste collection contractor. Private waste\ncollection must occur entirely within the confines of private\nproperty with an on -property service provided. Bins and bulky\nwaste are prohibited from being presented on the kerbside or in\nany public place and must be collected within the confines of\nprivate property. Private waste collection is limited to a once\nweekly collection, during the hours of 6 am - 10 pm, Monday to\nFriday. No weekend collections are permitted. The cost of a private\nwaste service and the responsibility for managing such service(S)\nin accordance with this condition lies with the NSW Land and\nHousing Corporation . Residential properties (units) may still be\nlevied for waste services in accordance with Council’s Fees and\nCharges for an administration fee or similar in accordance with the\nLocal Government Act 1993.\n(j) The management of organic landscaping waste must be removed\nfrom the site by licensed and suitably qualified contractors, and\ndisposed of at a licensed waste management facility, in the event\nthat onsite generation of landscaped material exceeds the\nvolume permissible to be collected in organic bins provided at the\nsite.\n(k) The development must allow 3m2 of storage space adjacent to\nthe bin storage area, drained to sewer with a water tap access\nthat meets the Building Code of Australia for use as a bin wash\narea.\n(l) NSW Land and Housing Corporation will be responsible for\nsubmitting a written request to Council to provide residential\nwaste services after construction is completed and prior to the\noccupation. The request must contain the Development Approval\nReference number, attached Residential Was te and Recycling\nServices Application Form (or similar, available for download on\nCouncil’s website) and relevant Crown Certificate. The provision\nof services is subject to completion of the on-site risk assessment.\nThe applicant must allow at least four weeks for the processing\nof the application, attendance at an on- site risk assessment and\nsubsequent bin delivery. It will be the responsibility of the NSW\nLand and Housing Corporation to manage and dispose of any\nwaste generated on the property if residents move in before such\na request is submitted, and bin delivery has been completed. The\nsize and number of bins provided by the Council may vary from\nthe Waste Management Plan (at Council’s discretion) depending\non bin availability, collection arrangements and property details.\n84. Vehicular entry and exit - Vehicular entry/exit movements shall be\ncarried out in a forward direction at all times.\n85. Carpark design and layout - The layout and design of off street car\nparking areas shall comply with the requirements of AS/NZS\n2890.1:2004 Parking Facilities, Part 1 - Off Street Car parking and\nother Australian Standards as applicable.\n86. Marking of parking spaces - Prior to the issue of the applicable\nCrown Certificate, all parking spaces shall be clearly designated and\nlinemarked to comply with AS1742, Manual of uniform Traffic\nControl Devices.\n87. Bicycle facilities - Facilities for the parking of bicycles either at\ngrade or in a basement car park area shall comply with the\nrequirements of AS2890.3: 2015 Parking Facilities, Part 3: Bicycle\nparking.\n88. Annual Fire Safety Statement - The owner of the building\npremises must ensure the Council is given an annual fire safety\nstatement in relation to each essential fire safety measure\nimplemented in the building. The annual fire safety statement\nmust be given:\n(a) Within 12 months after the date on which the fire safety\ncertificate was received.\n(b) Subsequent annual fire safety statements are to be given\nwithin 12 months after the last such statement was given.\n(c) An annual fire safety statement is to be given in or to the\neffect of Clause 181 of the Environmental Planning and\nAssessment Regulation 2000.\n(d) A copy of the statement is to be given to the Commissioner\nof Fire & Rescue NSW, and a further copy is to be\nprominently displayed in the building.\n89. Ongoing Tree Maintenance Works\na) All newly planted trees and plants must be maintained.\nMaintenance includes watering, weeding, removal of\nrubbish from tree bases, fertilising, pest and disease control,\nreplacement of dead or dying trees and other operations\nrequired to maintain healthy trees, plants and turfed areas.\nb) Trees must be maintained until they reach a height where\nthey are protected by Council’s Tree Management Controls.\nIf any trees are found to be faulty, damaged, dying or dead\nbefore they are protected by Council ’s Tree Management\nControls, then they must be replaced with the same species\nand pot/bag size.\nc) Mature trees shall be inspected for health and structural\nintegrity by an AQF Level 5 Arborist 12 -month post\ncompletion of works. A certificate of compliance and/or\nreport with recommendations for remedial work will be\nrequired to be approved by Council’s Tree Compliance\nOfficer.\n90. Amenity of the neighbourhood - The implementation of this\ndevelopment shall not adversely affect the amenity of the\nneighbourhood or interfere unreasonably with the comfort or\nrepose of a person who is outside the premises by reason of the\nemission or discharge of noise, fumes, vapour, odour, steam, soot,\ndust, waste water, waste products, grit, oil or other harmful\nproducts.\nPRESCRIBED CONDITIONS\nNot Applicable - Pursuant to Division 4.6 of the Environmental\nPlanning and Assessment Act, 1979, the consent authority cannot\nimpose conditions on a consent for which the Crown is the applicant,\nwithout the approval of the Minister.\nEND CONDITIONS\nNOTES / ADVICES\n1. Lapsing of Consent - This consent will lapse unless the\ndevelopment is physically commenced within 5 years from the\nDate of Operation of this consent, in accordance with Section 4.53\nof the Environmental Planning and Assessment Act 1979 as\namended.\n2. Access to NSW Legislations (Acts, Regulations and Planning\nInstruments) - NSW legislation can be accessed free of charge at\nwww.legislation.nsw.gov.au\n3. Noise - Noise related conditions - Council will generally enforce\nnoise related conditions in accordance with the Noise Guide for\nLocal Government\n(http://www.environment.nsw.gov.au/noise/nglg.htm) and the\nIndustrial Noise Guidelines\n(http://www.environment.nsw.gov.au/noise/industrial.htm)\npublished by the Department of Environment and\nConservation. Other state government authorities also\nregulate the Protection of the Environment Operations Act\n1997.\nUseful links relating to Noise:\n(a) Community Justice Centres - free mediation service provided\nby the NSW Government (www.cjc.nsw.gov.au).\n(b) Department of Environment and Conservation NSW, Noise\nPolicy Section web page\n(www.environment.nsw.gov.au/noise).\n(c) New South Wales Government Legislation home page for\naccess to all NSW legislation, including the Protection of the\nEnvironment Operations Act 1997 and the Protection of the\nEnvironment Noise Control Regulation 2000\n(www.legislation.nsw.gov.au).\n(d) Australian Acoustical Society - professional society of noise -\nrelated professionals (www.acoustics.asn.au/index.php).\n(e) Association of Australian Acoustical Consultants -\nprofessional society of noise related professionals\n(www.aaac.org.au).\n(f) Department of Gaming and Racing - (www.dgr.nsw.gov.au).\n4. Sydney Water Section 73 Certificates - The Section 73 Certificate\nmust be a separate certificate that relates specifically to this\ndevelopment consent. For example, if the development consent\nrelates to the subdivision of the land, a Section 73 Certificate for\nthe construction of the building that is subject to a different\ndevelopment consent will not suffice.\n5. Electricity Supply - This development may need a connection to the\nAusgrid network which may require the network to be extended or\nits capacity augmented. You are advised to contact Ausgrid on 13\n13 65 or www.ausgrid.com.au (Business and Commercial Services)\nfor further details and information on lodging your application to\nconnect to the network.\n6. Long Service Levy - The Long Service Corporation administers a\nscheme which provides a portable long service benefit for eligible\nworkers in the building and construction industry in NSW. All\nbenefits and requirements are determined by the Building and\nConstruction Industry Long Service Payments Act 1986. More\ninformation about the scheme and the levy amount you are\nrequired to pay to satisfy a condition of your consent can be found\nat http://www.longservice.nsw.gov.au.\nThe required Long Service Levy payment can be direct to the\nLong Service Corporation via their web site\nhttps://online.longservice.nsw.gov.au/bci/levy. Payments can\nonly be processed on- line for the full levy owing and where\nthe value of work is between $25,000 and $6,000,000.\nPayments will be accepted for amounts up to $21,000, using\neither MasterCard or Visa.\n7. Site Safety Fencing - Site fencing must be erected in accordance\nwith SafeWork Guidelines, to exclude public access to the site\nthroughout the demolition and/or construction work, except in the\ncase of alterations to an occupied dwelling. The fencing must be\nerected before th e commencement of any work and maintained\nthroughout any demolition and construction work.\nA demolition licence and/or a high- risk work license may be\nrequired from SafeWork NSW (see www.SafeWork.nsw.gov.au).\n91. 69 EPAR 2021 - Building Code of Australia & Home\nBuilding Act 1989\nRequires all building work to be carried out in accordance with\nthe Building Code of Australia. In the case of residential building\nwork to which the Home Building Act 1989 relates, there is a\nrequirement for a contract of insurance to be in force before any\nwork commences.\n92. 70 EPAR 2021 - Erection of Signs - Requires the erection\nof signs on site and outlines the details which are to be\nincluded on the sign. The sign must be displayed in a\nprominent position on site and include the name and contact\ndetails of the Crown Certifier and the Principal Contractor.\n93. 71 EPAR 2021 - Home Building Act 1989 - If the\ndevelopment involves residential building work under the\nHome Building Act 1989, no work is permitted to commence\nunless certain details are provided in writing to Council. The\nname and licence/permit number of the Principal Contractor\nor Owner Builder and the name of the Insurer by which work\nis insured under Part 6 of the Home Building Act 1989.\nIf you need more information, please contact the Development\nAssessment Planner, below on 9330-6400 between 9.00am -\n11.00am business days.\nRuth Bennett\nPrincipal Planner","stage":"general","stage_basis":"heading","page":33}]});
